let hlsLoader = null;
let midiLoader = null;
export const registerFileViewerHlsLoader = (loader) => {
    hlsLoader = loader;
};
export const registerFileViewerMidiLoader = (loader) => {
    midiLoader = loader;
};
export const getFileViewerHlsLoader = () => hlsLoader;
export const getFileViewerMidiLoader = () => midiLoader;
